SELECT Имена_станций.NAME AS Name1, [Станции(архив)].year, [Станции(архив)].nust, [Станции(архив)].E, [Станции(архив)].B, [Станции(архив)]!DON/IIf(Натура99!DON>0,Натура99!DON,0.699) AS don, [Станции(архив)]!podm/IIf(Натура99!podm>0,Натура99!podm,0.274) AS podm, IIf([int]>0,[int],0)+IIf([vork]>0,[vork],0) AS pech, [Доп_угли(архив)]!vork/IIf(Натура99!vork>0,Натура99!vork,0.677) AS Vork, [Доп_угли(архив)]!int/IIf(Натура99!int>0,Натура99!int,0.532) AS [int], [Станции(архив)]!kuzn/IIf(Натура99!kuzn>0,Натура99!kuzn,0.752) AS kuzn, IIf([sver]>0,[sver],0)+IIf([chel]>0,[chel],0)+IIf([kizel]>0,[kizel],0) AS Ural, [Доп_угли(архив)]!sver/IIf(Натура99!sver>0,Натура99!sver,0.316) AS sver, [Доп_угли(архив)]!chel/IIf(Натура99!chel>0,Натура99!chel,0.422) AS chel, [Доп_угли(архив)]!kizel/IIf(Натура99!kizel>0,Натура99!kizel,0.624) AS kizel, [Станции(архив)]!bashk/IIf(Натура99!bashk>0,Натура99!bashk,0.29) AS bashk, [Станции(архив)]!ekib/IIf(Натура99!ekib>0,Натура99!ekib,0.551) AS ekib, [Станции(архив)]!karag/IIf(Натура99!karag>0,Натура99!karag,0.502) AS karag, IIf([nazar]>0,[nazar],0)+IIf([ibor]>0,[ibor],0)+IIf([berez]>0,[berez],0)+IIf([per]>0,[per],0) AS kan, [Доп_угли(архив)]!nazar/IIf(Натура99!nazar>0,Натура99!nazar,0.484) AS nazar, [Доп_угли(архив)]!ibor/IIf(Натура99!ibor>0,Натура99!ibor,0.537) AS ibor, [Доп_угли(архив)]!berez/IIf(Натура99!berez>0,Натура99!berez,0.519) AS berez, [Доп_угли(архив)]!per/IIf(Натура99!per>0,Натура99!per,0.537) AS per, IIf([azey]>0,[azey],0)+IIf([cher]>0,[cher],0) AS irkut, [Доп_угли(архив)]!azey/IIf(Натура99!azey>0,Натура99!azey,0.554) AS azey, [Доп_угли(архив)]!cher/IIf(Натура99!cher>0,Натура99!cher,0.613) AS cher, [Станции(архив)]!hak/IIf(Натура99!hak>0,Натура99!hak,0.656) AS hak, [Станции(архив)]!tuv/IIf(Натура99!tuv>0,Натура99!tuv,0.781) AS tuv, IIf([gusin]>0,[gusin],0)+IIf([tugn]>0,[tugn],0) AS bur, [Доп_угли(архив)]!gusin/IIf(Натура99!gusin>0,Натура99!gusin,0.528) AS gusin, [Доп_угли(архив)]!tugn/IIf(Натура99!tugn>0,Натура99!tugn,0.708) AS tugn, [Станции(архив)]!chit/IIf(Натура99!chit>0,Натура99!chit,0.434) AS chit, [Станции(архив)]!ner/IIf(Натура99!her>0,Натура99!her,0.876) AS ner, [Станции(архив)]!raich/IIf(Натура99!raich>0,Натура99!raich,0.38) AS raich, [Станции(архив)]!urg/IIf(Натура99!urg>0,Натура99!urg,0.645) AS urg, [Станции(архив)]!prim/IIf(Натура99!prim>0,Натура99!prim,0.388) AS prim, [Станции(архив)]!luch/IIf(Натура99!luch>0,Натура99!luch,0.256) AS luch, [Станции(архив)]!mag/IIf(Натура99!mag>0,Натура99!mag,0.64) AS mag, [Станции(архив)]!sah/IIf(Натура99!sah>0,Натура99!sah,0.596) AS sah, [Станции(архив)].numb1120, Имена_станций.ordnumb AS numb1, [Станции(архив)].dep, [Станции(архив)].oes, [Станции(архив)].er, Имена_областей.NAME AS oblname, [Станции(архив)].ved, IIf([Станции(архив)]!VED<3,1,2) AS вед, [Станции(архив)].obl, Имена_станций.D, Имена_станций.R, Имена_ОЭС.name AS oesname, Имена_станций.MAIN
FROM (((([Станции(архив)] LEFT JOIN Натура99 ON ([Станции(архив)].numb1120=Натура99.NUMB1120) AND ([Станции(архив)].year=Натура99.YEAR)) LEFT JOIN [Доп_угли(архив)] ON ([Станции(архив)].year=[Доп_угли(архив)].YEAR) AND ([Станции(архив)].numb1120=[Доп_угли(архив)].NUMB1120)) INNER JOIN Имена_станций ON [Станции(архив)].numb1120=Имена_станций.NUMB) INNER JOIN Имена_областей ON [Станции(архив)].obl=Имена_областей.OBL) INNER JOIN Имена_ОЭС ON [Станции(архив)].oes=Имена_ОЭС.oes
WHERE ((([Станции(архив)].year)=2000) AND (([Станции(архив)].ugol)>0));
